import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CWdVbaJB.js";const n="/shavira-docs/screenshots/findings.png",g=JSON.parse('{"title":"Security Overview","description":"","frontmatter":{"title":"Security Overview"},"headers":[],"relativePath":"security/overview.md","filePath":"security/overview.md"}'),o={name:"security/overview.md"};function r(c,e,d,l,h,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="security-overview" tabindex="-1">Security Overview <a class="header-anchor" href="#security-overview" aria-label="Permalink to &quot;Security Overview&quot;">​</a></h1><p>SHAVIRA is a security product, so its own security posture matters. This page explains how SHAVIRA turns AI traces into security signal, and how it protects the data you send it — the authentication model, multi-tenant isolation, and data handling <strong>as they are actually implemented</strong>.</p><h2 id="the-trace-first-security-model" tabindex="-1">The trace-first security model <a class="header-anchor" href="#the-trace-first-security-model" aria-label="Permalink to &quot;The trace-first security model&quot;">​</a></h2><p>SHAVIRA treats every LLM call, tool invocation, and agent decision as structured telemetry, then analyzes that telemetry for security issues. Because the data is captured at the trace level, detections have full context: the prompt, the model, the tools used, the end user, and the outcome. Security analysis runs <em>on your observability data</em> rather than as a separate, bolted-on scanner.</p><h2 id="detections-→-findings-pipeline" tabindex="-1">Detections → findings pipeline <a class="header-anchor" href="#detections-→-findings-pipeline" aria-label="Permalink to &quot;Detections → findings pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ingested events → Detection rules (Sigma) → Findings → Triage workflow</span></span></code></pre></div><ol><li><strong>Ingest.</strong> Events arrive over the SDK endpoint or OTLP and are stored as workspace-scoped rows.</li><li><strong>Detect.</strong> Sigma-based <a href="/shavira-docs/security/detection-rules.html">detection rules</a> — built-in and custom — evaluate against ingested events. Rules carry a severity and optional <a href="/shavira-docs/security/attack-mapping.html">MITRE ATT&amp;CK</a> technique IDs, and every edit is versioned.</li><li><strong>Finding.</strong> A match produces a <a href="/shavira-docs/security/findings.html">finding</a> with severity, confidence, evidence links, ATT&amp;CK mapping, and detection artifacts (Sigma rule, SIEM query hints).</li><li><strong>Triage.</strong> Findings move through a workflow — <code>open → investigating → resolved</code> / <code>false_positive</code> — with assignment, comments, and bulk actions. Every action is audit-logged.</li></ol><p><img src="'+n+'" alt="SHAVIRA Findings view listing security findings with severity, status, assignee, and ATT&amp;CK mapping"></p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>SHAVIRA supports two credential types, each for a distinct caller:</p><table tabindex="0"><thead><tr><th>Credential</th><th>Used by</th><th>How it&#39;s sent</th></tr></thead><tbody><tr><td><strong>JWT session</strong></td><td>The web UI (human users)</td><td>Signed token in an <code>httpOnly</code> cookie</td></tr><tr><td><strong>API key (<code>shv_…</code>)</strong></td><td>SDKs and OTLP exporters (machines)</td><td><code>Authorization: Bearer shv_…</code></td></tr></tbody></table><ul><li>The web session uses short-lived access tokens with longer-lived refresh, stored in <code>httpOnly</code> cookies so they are not reachable from page JavaScript.</li><li>API keys are bound to a <strong>workspace</strong> and, optionally, a single <strong>project</strong>. A key authenticates <em>which workspace/project</em> the data belongs to — never the <em>content</em> of the data.</li><li>All API routes except the health check and the auth/ingest receivers sit behind authentication middleware; unauthenticated requests are rejected with <code>401</code>.</li></ul><h2 id="multi-tenant-workspace-isolation" tabindex="-1">Multi-tenant workspace isolation <a class="header-anchor" href="#multi-tenant-workspace-isolation" aria-label="Permalink to &quot;Multi-tenant workspace isolation&quot;">​</a></h2><p>The workspace is the hard tenant boundary. Isolation is enforced on <strong>every</strong> read and write, not just at login:</p><ul><li><strong>Ingest is workspace-bound.</strong> Data POSTed with a <code>shv_</code> key can only ever land in that key&#39;s own workspace. A forged or copied ID that points at another tenant simply resolves to &quot;not in this workspace&quot; — no data crosses.</li><li><strong>Reads are workspace-scoped.</strong> Trace, finding, session, end-user, and stream endpoints all filter by the caller&#39;s <code>workspace_id</code>. One tenant cannot query another tenant&#39;s rows.</li><li><strong>Per-project RBAC.</strong> Within a workspace, access is further scoped by project. Workspace <strong>admins</strong> see all projects; <strong>members</strong> and <strong>viewers</strong> see only projects they belong to. Project roles (<code>admin</code> / <code>analyst</code> / <code>viewer</code>) govern what each member can do. Access checks run on list, detail, session, and live-stream routes alike, and denied cross-project access attempts are logged.</li></ul><h2 id="data-handling" tabindex="-1">Data handling <a class="header-anchor" href="#data-handling" aria-label="Permalink to &quot;Data handling&quot;">​</a></h2><ul><li><strong>Self-hosted.</strong> SHAVIRA runs in your own environment (Docker Compose by default). Trace data lives in <em>your</em> PostgreSQL — it is not sent to a third party.</li><li><strong>Untrusted content is treated as untrusted.</strong> Trace payloads, exception messages, and OTLP span events/links are attacker-influenceable free text. The UI renders them as escaped text (React&#39;s default), and the API avoids logging raw payloads, so malicious trace content can&#39;t turn into script execution or leak into logs.</li><li><strong>Input validation at the boundary.</strong> Every ingest and API request body is validated against a Zod schema before it is processed or stored.</li><li><strong>Rate limiting &amp; abuse controls.</strong> Login attempts, session/end-user reads, exports, and live SSE connections are each rate-limited per user or per workspace to blunt brute-force and resource-exhaustion attempts.</li><li><strong>Audit trails.</strong> Security-relevant actions — auth events, finding changes, project and membership changes — are written to append-only audit and auth logs.</li></ul><div class="warning custom-block"><p class="custom-block-title">Secrets in traces</p><p>Instrumentation can accidentally capture secrets (tokens, credentials, PII) inside prompts, outputs, or stack traces. SHAVIRA stores and isolates what it receives, but the cleanest defense is to avoid sending sensitive values into traces in the first place. Scrub or redact at the source in your SDK integration.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/shavira-docs/security/detection-rules.html">Detection Rules</a> — write and tune Sigma rules</li><li><a href="/shavira-docs/security/findings.html">Findings &amp; Workflows</a> — triage findings end to end</li><li><a href="/shavira-docs/security/attack-mapping.html">ATT&amp;CK Mapping</a> — map detections to MITRE techniques</li><li><a href="/shavira-docs/concepts/architecture.html">Architecture</a> — how ingest, storage, and the UI fit together</li></ul>',20)])])}const m=t(o,[["render",r]]);export{g as __pageData,m as default};
